import 'package:flutter/material.dart';

/// AI daily planner (owner PART 2, flag ai_daily_planner) — bilingual string
/// table in the Task Manager style ([bn, en] pairs, Bangla as code points so
/// no Bangla glyph lives in Dart source). Digits go through ld()/dpNum.

bool dpIsBn(BuildContext c) => Localizations.localeOf(c).languageCode == 'bn';

String dpStr(BuildContext c, String key) {
  final pair = _dp[key];
  if (pair == null) return key;
  return dpIsBn(c) ? pair[0] : pair[1];
}

/// Fill {name} placeholders; values are digit-localised by the caller.
String dpFill(BuildContext c, String key, Map<String, String> v) {
  var s = dpStr(c, key);
  v.forEach((k, val) => s = s.replaceAll('{$k}', val));
  return s;
}

